"""Render docs/data/source-register.md from the country adapters (single source of truth)."""

import sys

sys.path.insert(0, "backend")
from app.countries.registry import ADAPTERS  # noqa: E402

out = ["# Source, provenance and licensing register", "",
       "Generated by `ops/docs/gen_source_register.py` from the country adapters. Runtime status (last success, "
       "freshness, open quarantine) is shown live in the app's Source registry.", ""]
for code, ad in ADAPTERS.items():
    out += [f"## {ad.name} ({code})", ""]
    for s in ad.sources():
        out += [f"### {s.name} (`{s.key}`)", "",
                "| Field | Value |", "|---|---|",
                f"| Publisher | {s.publisher} |", f"| Internal owner | {s.owner_team} |",
                f"| Homepage | {s.homepage_url} |", f"| Access method | {s.access_method} |",
                f"| Access details | {s.access_details} |", f"| Access terms | {s.access_terms} |",
                f"| Licence | {s.license} |", f"| Redistribution permitted | {s.permits_redistribution} |",
                f"| Text analysis permitted | {s.permits_text_analysis} |",
                f"| Refresh schedule | {s.refresh_schedule} |", f"| Freshness SLA (h) | {s.freshness_sla_hours} |",
                f"| Coverage | {s.coverage} |", f"| Reliability notes | {s.reliability_notes} |",
                f"| Adapter | `{s.adapter_key}` |", f"| Credentials required | {', '.join(s.required_credentials) or 'none'} |",
                f"| Initial status | **{s.default_status}** |", f"| Status reason | {s.status_reason or '—'} |",
                f"| Remediation | {s.remediation or '—'} |", f"| Verification of access method | {s.verification} |",
                f"| Synthetic | {s.is_synthetic} |", ""]
out += ["## Provenance recorded for every ingested artefact", "",
        "`raw_files`: source, URL (secrets redacted), publisher, retrieval time, SHA-256, size, content type, storage "
        "key (content-addressed, write-once), schema version, HTTP metadata. `ingestion_runs`: adapter key and "
        "version, parameters, idempotency key, raw file ids, stats, data-quality checks, status, error, trigger. "
        "Every derived contest, candidacy and result snapshot stores `source_id` and `ingestion_run_id`.", ""]
open("docs/data/source-register.md", "w").write("\n".join(out))
print("written", sum(len(a.sources()) for a in ADAPTERS.values()), "sources")
